// Rebuilds src/worker/data/disposable-domains.ts from two public lists of throw-away email domains:
// disposable-email-domains (curated, CC0) and FakeFilter (tracks rotating temp-mail services daily).
// Run: node scripts/update-disposable-domains.mjs   (then commit the regenerated file)
import { writeFileSync } from "node:fs";

const SOURCES = [
  "https://raw.githubusercontent.com/disposable-email-domains/disposable-email-domains/main/disposable_email_blocklist.conf",
  "https://raw.githubusercontent.com/7c/fakefilter/main/txt/data.txt",
];
// Never block these, whatever a list says.
const KEEP = new Set(["gmail.com", "googlemail.com", "outlook.com", "hotmail.com", "live.com", "msn.com", "yahoo.com", "icloud.com", "me.com", "proton.me", "protonmail.com", "aol.com", "gmx.com", "zoho.com", "yandex.com", "mail.ru"]);

const domains = new Set();
for (const url of SOURCES) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
  for (const line of (await r.text()).split("\n")) {
    const d = line.trim().toLowerCase();
    if (d && !d.startsWith("#") && /^[a-z0-9.-]+\.[a-z]{2,}$/.test(d) && !KEEP.has(d)) domains.add(d);
  }
}
const list = [...domains].sort();
writeFileSync(
  new URL("../src/worker/data/disposable-domains.ts", import.meta.url),
  `// Generated by scripts/update-disposable-domains.mjs on ${new Date().toISOString().slice(0, 10)} — ${list.length} domains. Do not edit by hand.\nexport const DISPOSABLE_DOMAINS_TEXT = ${JSON.stringify(list.join("\n"))};\n`,
);
console.log(`${list.length} domains`);
